/** Thrown when a percent-encoding is not followed by two hex digits. */
export class PercentError extends Error {
  constructor(component) {
    super(`the ${component} has a truncated percent-encoding`)
    this.component = component
  }
}

const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

/**
 * Splits a URI reference string into its generic-syntax components.
 * Presence and absence are tracked separately from emptiness: hasScheme,
 * hasAuthority, hasQuery and hasFragment are false when the component is
 * absent, even if the corresponding string would otherwise be ''.
