  let rest = str
  let hasScheme = false
  let scheme

  let colonIdx = -1
  for (let i = 0; i < rest.length; i++) {
    const c = rest[i]
    if (c === ':') {
      colonIdx = i
      break
    }
    if (c === '/' || c === '?' || c === '#') break
  }
  if (colonIdx !== -1) {
    hasScheme = true
    scheme = rest.slice(0, colonIdx)
    rest = rest.slice(colonIdx + 1)
