  let hasQuery = false
  let query
  let path
  if (queryIdx === -1) {
    path = beforeFragment
  } else {
    path = beforeFragment.slice(0, queryIdx)
    hasQuery = true
    query = beforeFragment.slice(queryIdx + 1)
  }

  let userinfo = null
  let host = ''
  let hasPort = false
  let port = ''
  if (hasAuthority) {
